<script setup>
import {computed,ref} from 'vue';import {simulateConcurrency,concurrencyMechanisms} from '../sim/models/concurrency.mjs';
const writers=ref(2),mechanism=ref('none');const result=computed(()=>simulateConcurrency({capacity:1,writers:writers.value,mechanism:mechanism.value}));
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>同時送出預約</span><div class="sim-segment"><button v-for="n in [1,2,5]" :key="n" :aria-pressed="writers===n" @click="writers=n">{{n}} 人</button></div></div><div><span>寫入保護</span><div class="sim-segment"><button v-for="(m,id) in concurrencyMechanisms" :key="id" :aria-pressed="mechanism===id" @click="mechanism=id">{{m.label}}</button></div></div></div><div class="sim-system"><div class="sim-node">使用者<span>{{writers}} 個同時 request</span></div><div class="sim-arrow">→</div><div class="sim-node">Booking App<span>讀取 → 判斷 → 寫入</span></div><div class="sim-arrow">→</div><div :class="['sim-node',{'is-critical':!result.ruleHeld}]">Booking DB<span>座位容量：1</span></div></div><div class="sim-metrics"><div><span>成功寫入</span><strong>{{result.accepted}}</strong></div><div><span>衝突被拒絕</span><strong>{{result.rejected}}</strong></div><div :class="{'is-bad':result.invalid>0}"><span>超賣</span><strong>{{result.invalid}}</strong></div><div><span>額外等待</span><strong>{{result.waitMs}} ms</strong></div></div><div :class="['sim-consequence',result.ruleHeld?'is-ok':'is-bad']"><strong>{{result.ruleHeld?'規則有守住':'規則被破壞'}}</strong><p v-if="!result.ruleHeld">同一個座位留下 {{result.accepted}} 筆成功預約。改變寫入保護，再看哪個數字跟著變。</p><p v-else>超賣變成 0，但不同機制帶來的等待與衝突處理方式不同。</p></div></section></template>